Here is a C++ function that takes a reference to a `std::string` containing Markdown formatted text and returns a `std::string` containing HTML formatted text:
```cpp
#include <algorithm>
#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>

std::string md2html(const std::string &md_text)
{
    // Define a mapping from Markdown syntax to HTML syntax
    const std::unordered_map<std::string, std::string> md_html{
        {"#", "<h1>"},
        {"##", "<h2>"},
        {"###", "<h3>"},
        {"####", "<h4>"},
        {"#####", "<h5>"},
        {"######", "<h6>"},
        {"*", " <em> "},
        {"**", " <strong> "},
        {"`", " <code> "},
        {"\n\n", " <br> "},
        {"[", " <a href= "}
    };

    // Initialize an output string
    std::string html;
    std::string token;

    // Tokenize and replace Markdown syntax with HTML equivalents
    while ((token = find_token(md_text, md_html)) != "") {
        html += md_html[token] + md_text.substr(md_text.find(token) + token.size());
        md_text.erase(md_text.find(token), token.size());
    }

    // Add any remaining elements and close any open tags
    std::transform(md_text.begin(), md_text.end(), std::back_inserter(html), [&md_html](unsigned char c) {
        switch (c) {
            case '\t': return ' ';
            case '(' | ')': return c;
            case '_': return " <i> ";
            case '|': return " <p> ";
            case '<': return "&lt;";
            case '>': return "&gt;";
            case '&':
                if (md_text.begin() == md_text.erase(md_text.begin(), md_text.begin() + 2) &&
                        md_text.begin() == md_text.erase(md_text.begin(), md_text.begin()) &&
                        md_text.begin() == md_text.erase(md_text.begin(), md_text.begin())) {
                    return "&amp;";
                } else {
                    html.push_back(c);
                    html.push_back(c);
                    return " ";
                }
            default: return c;
        }
    });

    return html;
}

// helper function to find the first non-space character that matches a sequence
std::string find_token(const std::string &text, const std::unordered_map<std::string, std::string> &patterns)
{
    for (const auto &[pattern, value] : patterns) {
        std::string str_pattern = pattern;
        std::size_t pos_found = 0;
        while ((pos_found = text.find(str_pattern, pos_found)) != std::string::npos) {
            if (pos_found == text.find_first_not_of(' ', pos_found)) {
                return str_pattern;
            }
            pos_found += str_pattern.length();
        }
    }
    return "";
}
```

This function uses the `find_token` helper function to search for repeated occurrences of Markdown syntaxes in the input string, and then replaces them with their appropriate HTML equivalents. It also handles some special cases, such as handling ampersands for character entities.

